import _ from 'lodash';
import { ref, type ComputedRef, type Ref } from 'vue';
import type { EditSnapshot } from '../EditKeyModal.vue';
import type { DataPath, ItemEntry, PrefixSuffixItem, RawData } from '../types';
import { getByPath } from '../utils/deep-utils';
import { persistRawData } from '../utils/persist';
import { isSingleKeyObject, updateContainerWithPayload } from '../utils/quicksend';

/** handleEditSave 的 payload 类型 */
export interface EditSavePayload {
  newName?: string;
  newValue?: string;
  children: Array<{ id: string; newName?: string; newValue?: string }>;
  __create?: boolean;
  __createAsLeaf?: boolean;
}

interface UseEditOperationsOptions {
  rawData: RawData;
  quickSendData: Ref<unknown[]>;
  prefixList: ComputedRef<PrefixSuffixItem[]>;
  suffixList: ComputedRef<PrefixSuffixItem[]>;
  level1Entries: ComputedRef<ItemEntry[]>;
  level2Entries: ComputedRef<ItemEntry[]>;
  activeTabIndex: Readonly<Ref<number>>;
  activeSecondIndex: Readonly<Ref<number>>;
  gridPath: Readonly<Ref<number[]>>;
  gridBaseEntry: ComputedRef<ItemEntry | null>;
  computeGridEntries: (node: unknown, basePath: DataPath) => {
    labels: string[];
    values: unknown[];
    metas: Array<{ path: DataPath }>;
  };
}

/**
 * 编辑操作 composable
 * 收敛 openEdit/openCreate/handleEditSave/handleCopy/handleCopyPrefixSuffix/handleDeleteById
 */
export function useEditOperations(opts: UseEditOperationsOptions) {
  const {
    rawData, quickSendData, prefixList, suffixList,
    level1Entries, level2Entries, activeTabIndex, activeSecondIndex,
    gridPath, gridBaseEntry, computeGridEntries,
  } = opts;

  const editOpen = ref(false);
  const editSnapshot = ref<EditSnapshot | null>(null);
  const editNodeId = ref<string | null>(null);
  const confirmDeleteId = ref<string | null>(null);

  // ── ID 工具 ──────────────────────────────────────────────

  function makeIdFromPath(path: DataPath): string {
    return JSON.stringify(path);
  }

  function parseId(id: string): DataPath {
    if (!id || id.startsWith('prefix:') || id.startsWith('suffix:')) return [];
    try {
      const parsed = JSON.parse(id);
      return Array.isArray(parsed) ? (parsed as DataPath) : [];
    } catch {
      return [];
    }
  }

  /** 根据 id 解析出容器、键、值等信息 */
  function resolveById(root: unknown[], id: string) {
    const path = parseId(id);
    if (path.length === 0) return null;
    const containerPath = path.slice(0, -1);
    const lastKey = path[path.length - 1];
    const container = containerPath.length === 0 ? root : getByPath(root, containerPath);
    if (container == null) return null;

    if (Array.isArray(container) && typeof lastKey === 'number') {
      const element = container[lastKey];
      if (typeof element === 'string') {
        return { container, keyInContainer: lastKey, title: `#${lastKey}`, value: element, canRename: false, isLeaf: true, path };
      }
      if (element && typeof element === 'object' && !Array.isArray(element) && isSingleKeyObject(element)) {
        const innerKey = Object.keys(element)[0];
        const innerValue = (element as any)[innerKey];
        return { container: element, keyInContainer: innerKey, title: innerKey, value: innerValue, canRename: true, isLeaf: typeof innerValue === 'string', path };
      }
      return { container, keyInContainer: lastKey, title: `#${lastKey}`, value: element, canRename: false, isLeaf: typeof element === 'string', path };
    }

    const value = getByPath(root, path);
    const title = typeof lastKey === 'string' ? lastKey : `#${lastKey}`;
    return { container, keyInContainer: lastKey as string | number, title, value, canRename: typeof lastKey === 'string', isLeaf: typeof value === 'string', path };
  }

  function makeIdForLevel1Idx(idx: number): string {
    const entry = level1Entries.value[idx];
    return makeIdFromPath(entry?.path ?? [idx]);
  }

  function makeIdForLevel2Idx(idx: number): string {
    const entry = level2Entries.value[idx];
    if (!entry) return makeIdForLevel1Idx(activeTabIndex.value);
    return makeIdFromPath(entry.path);
  }

  function makeIdForGridIdx(idx: number): string {
    const baseEntry = level2Entries.value[activeSecondIndex.value];
    if (!baseEntry) return makeIdForLevel1Idx(activeTabIndex.value);
    let current: unknown = baseEntry.value;
    let currentPath: DataPath = baseEntry.path;
    for (const stepIdx of gridPath.value) {
      const step = computeGridEntries(current, currentPath);
      const meta = step.metas[stepIdx];
      if (!meta) return makeIdFromPath(currentPath);
      current = step.values[stepIdx];
      currentPath = meta.path;
    }
    const step = computeGridEntries(current, currentPath);
    const targetMeta = step.metas[idx];
    return makeIdFromPath(targetMeta ? targetMeta.path : currentPath);
  }

  // ── 快照工具 ─────────────────────────────────────────────

  /** 为编辑弹窗创建子节点快照 */
  function makeChildrenSnapshot(node: unknown): EditSnapshot['children'] {
    const items: EditSnapshot['children'] = [];
    if (node == null) return items;
    if (typeof node === 'object' && !Array.isArray(node)) {
      for (const k of Object.keys(node as object)) {
        const v = (node as any)[k];
        items.push({ id: `key:${k}`, name: k, canRename: true, isLeaf: typeof v === 'string', value: typeof v === 'string' ? v : undefined });
      }
    } else if (Array.isArray(node)) {
      node.forEach((el, i) => {
        if (typeof el === 'string') {
          items.push({ id: `arridx:${i}`, name: `#${i}`, canRename: false, isLeaf: true, value: el });
        } else if (el && typeof el === 'object' && !Array.isArray(el) && isSingleKeyObject(el)) {
          const k = Object.keys(el)[0];
          const v = (el as any)[k];
          items.push({ id: `arridx:${i}`, name: k, canRename: true, isLeaf: typeof v === 'string', value: typeof v === 'string' ? v : undefined });
        } else {
          items.push({ id: `arridx:${i}`, name: `#${i}`, canRename: false, isLeaf: false });
        }
      });
    }
    return items;
  }

  // ── 打开编辑/创建 ─────────────────────────────────────────

  /** 打开编辑弹窗（l1/l2/grid） */
  function openEdit(idx: number, scope: 'l1' | 'l2' | 'grid') {
    const id = scope === 'grid' ? makeIdForGridIdx(idx) : scope === 'l2' ? makeIdForLevel2Idx(idx) : makeIdForLevel1Idx(idx);
    const resolved = resolveById(quickSendData.value, id);
    if (!resolved) return;
    editNodeId.value = id;
    editSnapshot.value = {
      title: resolved.title, name: resolved.title, canRename: resolved.canRename,
      isLeaf: resolved.isLeaf, value: resolved.isLeaf ? (resolved.value as string) : undefined,
      children: makeChildrenSnapshot(resolved.value),
    };
    editOpen.value = true;
  }

  /** 打开创建弹窗（l1/l2/grid） */
  function openCreate(scope: 'l1' | 'l2' | 'grid') {
    editNodeId.value = `__create__:${scope}`;
    editSnapshot.value = { title: '新建项', name: '', canRename: true, isLeaf: false, value: undefined, children: [], isCreate: true, createLevel: scope };
    editOpen.value = true;
  }

  /** 打开前后缀编辑弹窗 */
  function openEditPrefixSuffix(idx: number, type: 'prefix' | 'suffix') {
    const list = type === 'prefix' ? prefixList.value : suffixList.value;
    const item = list[idx];
    if (!item) return;
    const key = getPrefixSuffixKey(item);
    const value = getPrefixSuffixValue(item);
    editNodeId.value = `${type}:${idx}`;
    editSnapshot.value = { title: key, name: key, canRename: true, isLeaf: true, value, children: [] };
    editOpen.value = true;
  }

  /** 打开创建前后缀弹窗 */
  function openCreatePrefixSuffix(type: 'prefix' | 'suffix') {
    editNodeId.value = `__create__:${type}`;
    editSnapshot.value = { title: type === 'prefix' ? '新建前缀' : '新建后缀', name: '', canRename: true, isLeaf: true, value: '', children: [], isCreate: true };
    editOpen.value = true;
  }

  // ── 保存 ─────────────────────────────────────────────────

  /** 处理编辑保存 */
  function handleEditSave(payload: EditSavePayload) {
    const id = editNodeId.value;
    if (!id) return;
    if (id.startsWith('__create__:')) {
      handleCreateInScope(id.slice(11) as 'l1' | 'l2' | 'grid' | 'prefix' | 'suffix', payload);
    } else if (id.startsWith('prefix:') || id.startsWith('suffix:')) {
      handlePrefixSuffixSave(id, payload);
    } else {
      handleGenericEditSave(id, payload);
    }
    persistRawData(rawData);
    closeEditModal();
  }

  /** 处理新建操作 */
  function handleCreateInScope(scope: 'l1' | 'l2' | 'grid' | 'prefix' | 'suffix', payload: EditSavePayload) {
    const newName = payload.newName || '新项';
    if (scope === 'prefix') {
      const list = rawData.perfix || rawData.prefix;
      if (!list) { rawData.prefix = []; }
      (rawData.perfix || rawData.prefix)!.push({ [newName]: payload.newValue ?? '' });
    } else if (scope === 'suffix') {
      if (!rawData.suffix) rawData.suffix = [];
      rawData.suffix.push({ [newName]: payload.newValue ?? '' });
    } else if (scope === 'l1') {
      quickSendData.value.push({ [newName]: [] });
    } else if (scope === 'l2') {
      const l1Entry = level1Entries.value[activeTabIndex.value];
      if (l1Entry && Array.isArray(l1Entry.value)) l1Entry.value.push({ [newName]: [] });
    } else if (scope === 'grid') {
      createInGrid(newName, payload);
    }
  }

  /** 在 grid 当前层新建项 */
  function createInGrid(newName: string, payload: EditSavePayload) {
    const base = gridBaseEntry.value;
    if (!base) return;
    let target: unknown = base.value;
    for (const idx of gridPath.value) {
      const step = computeGridEntries(target, base.path);
      target = step.values[idx];
    }
    if (Array.isArray(target)) {
      target.push(payload.__createAsLeaf ? { [newName]: payload.newValue ?? '' } : { [newName]: [] });
    } else if (target && typeof target === 'object') {
      (target as any)[newName] = payload.__createAsLeaf ? (payload.newValue ?? '') : [];
    }
  }

  /** 处理前后缀保存 */
  function handlePrefixSuffixSave(id: string, payload: EditSavePayload) {
    const isPre = id.startsWith('prefix:');
    const idx = Number(id.slice(isPre ? 7 : 7));
    const list = isPre ? prefixList.value : suffixList.value;
    const item = list[idx];
    if (!item || typeof item !== 'object') return;
    const oldKey = Object.keys(item)[0];
    if (payload.newName && payload.newName !== oldKey) {
      delete (item as any)[oldKey];
      (item as any)[payload.newName] = payload.newValue ?? '';
    } else if (payload.newValue != null) {
      (item as any)[oldKey] = payload.newValue;
    }
  }

  /** 处理通用路径编辑保存 */
  function handleGenericEditSave(id: string, payload: EditSavePayload) {
    const resolved = resolveById(quickSendData.value, id);
    if (!resolved) return;
    updateContainerWithPayload({ container: resolved.container, keyInContainer: resolved.keyInContainer, payload });
  }

  function closeEditModal() {
    editOpen.value = false;
    editNodeId.value = null;
    editSnapshot.value = null;
  }

  // ── 复制 ─────────────────────────────────────────────────

  /** 复制 l1/l2/grid 项 */
  function handleCopy(idx: number, scope: 'l1' | 'l2' | 'grid') {
    const id = scope === 'grid' ? makeIdForGridIdx(idx) : scope === 'l1' ? makeIdForLevel1Idx(idx) : makeIdForLevel2Idx(idx);
    if (!id) return;
    const resolved = resolveById(quickSendData.value, id);
    if (!resolved) return;
    const { container, keyInContainer, path, value } = resolved;
    const lastPathKey = _.last(path);
    const secondLastPathKey = path.length >= 2 ? path[path.length - 2] : undefined;
    const isSingleKeyCase = _.isPlainObject(container) && isSingleKeyObject(container) && _.isString(keyInContainer) && (_.isNumber(secondLastPathKey) || _.isNumber(lastPathKey));

    if (isSingleKeyCase || (_.isPlainObject(container) && _.isString(keyInContainer))) {
      copyObjectEntry(container, keyInContainer as string, path, value, isSingleKeyCase, lastPathKey, secondLastPathKey);
    }
    persistRawData(rawData);
  }

  /** 复制对象类型条目（单键对象或普通对象） */
  function copyObjectEntry(container: any, oldKey: string, path: DataPath, value: unknown, isSingleKeyCase: boolean, lastPathKey: unknown, secondLastPathKey: unknown) {
    let newKey = `${oldKey}_副本`;
    let counter = 1;
    if (isSingleKeyCase) {
      const arrayIndex = _.isNumber(lastPathKey) ? lastPathKey : _.isNumber(secondLastPathKey) ? secondLastPathKey : null;
      if (arrayIndex !== null) {
        const parentPath = _.isNumber(lastPathKey) ? _.initial(path) : path.length >= 2 ? path.slice(0, -2) : [];
        const parentArr = _.isEmpty(parentPath) ? quickSendData.value : getByPath(quickSendData.value, parentPath);
        if (_.isArray(parentArr)) {
          while (parentArr.some((it: any) => _.isPlainObject(it) && isSingleKeyObject(it) && Object.keys(it)[0] === newKey)) {
            newKey = `${oldKey}_副本${counter++}`;
          }
          parentArr.splice((arrayIndex as number) + 1, 0, { [newKey]: _.cloneDeep(value) });
          return;
        }
      }
    }
    while (_.has(container, newKey)) newKey = `${oldKey}_副本${counter++}`;
    _.set(container, newKey, _.cloneDeep(value));
  }

  /** 复制前后缀项 */
  function handleCopyPrefixSuffix(idx: number, type: 'prefix' | 'suffix') {
    const list = type === 'prefix' ? prefixList.value : suffixList.value;
    if (!Array.isArray(list) || idx < 0 || idx >= list.length) return;
    const item = list[idx];
    if (!item || typeof item !== 'object') return;
    const oldKey = getPrefixSuffixKey(item);
    let newKey = `${oldKey}_副本`;
    let counter = 1;
    while (list.some((it: any) => it && typeof it === 'object' && !Array.isArray(it) && Object.keys(it)[0] === newKey)) {
      newKey = `${oldKey}_副本${counter++}`;
    }
    list.splice(idx + 1, 0, { [newKey]: _.cloneDeep(getPrefixSuffixValue(item)) });
    if (type === 'prefix') {
      if (rawData.perfix) rawData.perfix = list as any;
      else rawData.prefix = list as any;
    } else {
      rawData.suffix = list as any;
    }
    persistRawData(rawData);
  }

  // ── 删除 ─────────────────────────────────────────────────

  /** 删除指定 id 的条目 */
  function handleDeleteById(id: string) {
    if (!id) return;
    if (id.startsWith('prefix:')) {
      deletePrefixSuffix(id, 'prefix');
    } else if (id.startsWith('suffix:')) {
      deletePrefixSuffix(id, 'suffix');
    } else {
      deleteByPath(id);
    }
    persistRawData(rawData);
    confirmDeleteId.value = null;
  }

  function deletePrefixSuffix(id: string, type: 'prefix' | 'suffix') {
    const idx = Number(id.slice(type === 'prefix' ? 7 : 7));
    const list = type === 'prefix' ? prefixList.value : suffixList.value;
    if (!Array.isArray(list) || idx < 0 || idx >= list.length) return;
    list.splice(idx, 1);
    if (type === 'prefix') {
      if (rawData.perfix) rawData.perfix = list as any;
      else rawData.prefix = list as any;
    } else {
      rawData.suffix = list as any;
    }
  }

  function deleteByPath(id: string) {
    const resolved = resolveById(quickSendData.value, id);
    if (!resolved) return;
    const { container, keyInContainer, path } = resolved;
    if (Array.isArray(container)) {
      container.splice(keyInContainer as number, 1);
    } else if (typeof container === 'object' && container !== null) {
      delete (container as any)[keyInContainer];
      cleanupEmptyParent(path);
    }
  }

  /** 删除后若父容器变空则移除父容器元素 */
  function cleanupEmptyParent(path: DataPath) {
    try {
      const containerPath = path.slice(0, -1);
      const parentPath = containerPath.slice(0, -1);
      const idxInParent = containerPath[containerPath.length - 1];
      const parent = parentPath.length === 0 ? quickSendData.value : getByPath(quickSendData.value, parentPath);
      const container = containerPath.length === 0 ? quickSendData.value : getByPath(quickSendData.value, containerPath);
      if (parent && Array.isArray(parent) && typeof idxInParent === 'number' && container && typeof container === 'object' && Object.keys(container as object).length === 0) {
        (parent as unknown[]).splice(idxInParent, 1);
      }
    } catch { /* ignore */ }
  }

  // ── 前后缀工具 ───────────────────────────────────────────

  function getPrefixSuffixKey(item: unknown): string {
    if (item && typeof item === 'object' && !Array.isArray(item)) {
      const keys = Object.keys(item as object);
      if (keys.length > 0) return keys[0];
    }
    return '';
  }

  function getPrefixSuffixValue(item: unknown): string {
    if (item && typeof item === 'object' && !Array.isArray(item)) {
      const keys = Object.keys(item as object);
      if (keys.length > 0) {
        const v = (item as any)[keys[0]];
        return typeof v === 'string' ? v : String(v);
      }
    }
    return '';
  }

  return {
    editOpen, editSnapshot, editNodeId, confirmDeleteId,
    openEdit, openCreate, openEditPrefixSuffix, openCreatePrefixSuffix,
    handleEditSave, handleCopy, handleCopyPrefixSuffix, handleDeleteById,
    closeEditModal,
    makeIdForLevel1Idx, makeIdForLevel2Idx, makeIdForGridIdx,
    getPrefixSuffixKey, getPrefixSuffixValue,
  };
}
