import { definePreset } from '@primeuix/themes';
import Aura from '@primeuix/themes/aura';

/** 主题颜色接口 */
export interface ThemeColors {
  primaryColor?: string;
}

const DEFAULT_PRIMARY_COLOR = '#4a9eff';

const LIGHT_THEME = {
  background: '#f8fafc',
  surface: '#e7edf3',
  text: '#17202a',
  border: '#b9c5d1',
};

const DARK_THEME = {
  background: '#15161a',
  surface: '#252a31',
  text: '#eef2f7',
  border: '#3e4652',
};

/**
 * 创建 PrimeVue 色板
 */
function createColorScheme(theme: typeof LIGHT_THEME, primaryColor: string) {
  return {
    primary: {
      color: primaryColor,
      activeColor: primaryColor,
      hoverColor: primaryColor,
      contrastColor: theme.background,
    },
    highlight: {
      background: `color-mix(in srgb, ${primaryColor} 50%, transparent)`,
      focusBackground: '{highlight.background}',
      color: theme.background,
      focusColor: '{highlight.color}',
    },
    text: {
      color: theme.text,
      hoverColor: theme.text,
      mutedColor: `rgb(from ${theme.text} r g b / 0.55)`,
    },
    content: {
      background: theme.background,
      hoverBackground: theme.surface,
      borderColor: theme.border,
      color: theme.text,
      hoverColor: theme.text,
    },
    formField: {
      color: theme.text,
      background: theme.surface,
      filledBackground: theme.surface,
      filledHoverBackground: theme.surface,
      filledFocusBackground: theme.surface,
      disabledBackground: `color-mix(in srgb, ${theme.surface} 60%, transparent)`,
      borderColor: theme.border,
      hoverBorderColor: theme.border,
      paddingY: '0.5rem',
    },
    overlay: {
      select: {
        background: theme.background,
        borderColor: theme.border,
      },
      modal: {
        background: theme.background,
        borderColor: theme.border,
        padding: '1rem',
      },
      popover: {
        background: theme.background,
        borderColor: theme.border,
      },
    },
    list: {
      option: {
        focusBackground: `color-mix(in srgb, ${primaryColor} 18%, transparent)`,
      },
    },
  };
}

/**
 * 创建基于引用色的 PrimeVue 自定义预设
 * @param themeColors 主题颜色配置
 */
export function createCustomPreset(themeColors: ThemeColors) {
  const primaryColor = themeColors.primaryColor ?? DEFAULT_PRIMARY_COLOR;

  return definePreset(Aura, {
    semantic: {
      colorScheme: {
        light: createColorScheme(LIGHT_THEME, primaryColor),
        dark: createColorScheme(DARK_THEME, primaryColor),
      },
    },
    components: {
      button: {
        root: {
          sm: {
            paddingY: '0.3rem',
            paddingX: '0.5rem',
          },
          iconOnlyWidth: '1.5rem',
        },
      },
      iftalabel: {
        colorScheme: {
          light: {
            root: {
              color: LIGHT_THEME.text,
              focusColor: primaryColor,
              invalidColor: '{form.field.invalid.border.color}',
            },
          },
          dark: {
            root: {
              color: DARK_THEME.text,
              focusColor: primaryColor,
              invalidColor: '{form.field.invalid.border.color}',
            },
          },
        },
      },
      togglebutton: {
        root: {
          sm: {
            padding: '0rem',
          },
        },
        colorScheme: {
          light: {
            root: {
              background: LIGHT_THEME.background,
              checkedColor: LIGHT_THEME.background,
              checkedBackground: primaryColor,
              checkedBorderColor: LIGHT_THEME.border,
              borderColor: LIGHT_THEME.border,
            },
            content: {
              checkedBackground: '{togglebutton.checked.background}',
            },
          },
          dark: {
            root: {
              background: DARK_THEME.background,
              checkedColor: DARK_THEME.background,
              checkedBackground: primaryColor,
              checkedBorderColor: DARK_THEME.border,
              borderColor: DARK_THEME.border,
            },
            content: {
              checkedBackground: '{togglebutton.checked.background}',
            },
          },
        },
      },
      toggleswitch: {
        colorScheme: {
          light: {
            root: {
              checkedBackground: primaryColor,
            },
          },
          dark: {
            root: {
              checkedBackground: primaryColor,
            },
          },
        },
      },
      fileupload: {
        colorScheme: {
          light: {
            content: {
              padding: '0rem',
            },
          },
          dark: {
            content: {
              padding: '0rem',
            },
          },
        },
      },
      picklist: {
        controls: {
          gap: '0.75rem',
        },
      },
      dialog: {
        title: {
          fontSize: '1.25rem',
        },
      },
    },
  } as Parameters<typeof definePreset>[1]);
}
