import { nextTick, ref, watch } from 'vue';
import { useDraggable } from 'vue-draggable-plus';
import type { Ref } from 'vue';

/** useDragList 单实例配置 */
export interface DragListOptions<T> {
  /** 拖拽手柄选择器（如 '.drag-handle-l1'），省略则整项可拖 */
  handle?: string;
  /** 过滤不可拖拽元素的选择器，可选 */
  filter?: string;
  /** 可拖拽元素选择器，可选 */
  draggable?: string;
  /** 是否启用拖拽实例 */
  enabled?: Ref<boolean>;
  /** 拖拽过程中是否阻止 filter 元素触发（chips 移除图标场景） */
  preventOnFilter?: boolean;
  /** 拖拽结束后写回源数据的回调 */
  onCommit: (oldIndex: number, newIndex: number, dragList: T[]) => void;
}

/** useDragList 单实例返回值 */
export interface DragListReturn<T> {
  /** 拖拽副本列表（绑定到 v-for） */
  dragList: Ref<T[]>;
  /** 容器 DOM 引用（绑定到模板 ref） */
  containerRef: Ref<HTMLElement | null>;
  /** 设置容器 ref 的回调（用于动态 ref 场景） */
  setContainerRef: (el: unknown) => void;
}

/**
 * 拖拽列表工厂 composable
 * 封装 useDraggable + watch + onCommit 写回逻辑
 * 调用方只需传入源数据和 onCommit，无需关心初始化细节
 *
 * @param source 源数据的响应式引用
 * @param isDragging 全局拖拽状态标志（由外部共享）
 * @param options 拖拽配置
 */
export function useDragList<T>(
  source: Ref<T[]>,
  isDragging: Ref<boolean>,
  options: DragListOptions<T>,
): DragListReturn<T> {
  const dragList = ref<T[]>([]) as Ref<T[]>;
  const containerRef = ref<HTMLElement | null>(null);
  const enabled = options.enabled ?? ref(true);
  let initialized = false;
  let draggableInstance: ReturnType<typeof useDraggable> | null = null;

  // 源数据变化时同步到拖拽副本（拖拽中不同步，防止动画被打断）
  watch(source, val => {
    if (!isDragging.value) dragList.value = [...val];
  }, { immediate: true });

  /** 销毁当前拖拽实例并重置状态 */
  function destroyInstance(): void {
    draggableInstance?.destroy?.();
    draggableInstance = null;
    initialized = false;
  }

  // 容器挂载/卸载、编辑模式切换时初始化或销毁拖拽实例
  watch([containerRef, enabled], ([el, isEnabled]) => {
    if (el && isEnabled && !initialized) {
      initialized = true;
      const currentEl = el;
      nextTick(() => {
        if (!initialized || !enabled.value || containerRef.value !== currentEl) return;
        draggableInstance = useDraggable(currentEl, dragList, {
          handle: options.handle,
          filter: options.filter,
          draggable: options.draggable,
          preventOnFilter: options.preventOnFilter,
          animation: 150,
          onStart: () => { isDragging.value = true; },
          onEnd: (event: { oldIndex?: number; newIndex?: number; oldDraggableIndex?: number; newDraggableIndex?: number }) => {
            isDragging.value = false;
            const oldIndex = event.oldDraggableIndex ?? event.oldIndex;
            const newIndex = event.newDraggableIndex ?? event.newIndex;
            if (!isValidIndex(oldIndex, newIndex, dragList.value.length)) return;
            options.onCommit(oldIndex!, newIndex!, dragList.value);
          },
        });
      });
      return;
    }
    if (!el || !isEnabled) destroyInstance();
  });

  function setContainerRef(el: unknown) {
    containerRef.value = (el as HTMLElement) ?? null;
  }

  return { dragList, containerRef, setContainerRef };
}

/** 校验拖拽索引是否有效 */
function isValidIndex(old?: number, next?: number, len?: number): boolean {
  if (old == null || next == null || len == null) return false;
  if (old === next) return false;
  if (old < 0 || old >= len) return false;
  if (next < 0 || next >= len) return false;
  return true;
}
