import { onMounted, onUnmounted } from 'vue';

/** 酒馆用户名与角色名缓存：监听 CHAT_CHANGED 并提供 Macro 替换读取函数 */
export function useQuickSendNames() {
  let userName = '';
  let charName = '';

  /** 同步当前酒馆用户名与角色名 */
  function updateName(): void {
    userName = SillyTavern.name1;
    charName = SillyTavern.name2;
  }

  onMounted(() => {
    eventOn(tavern_events.CHAT_CHANGED, updateName);
    updateName();
  });

  onUnmounted(() => {
    eventRemoveListener(tavern_events.CHAT_CHANGED, updateName);
  });

  return {
    userName: () => userName,
    charName: () => charName,
  };
}
