import { computed, ref, toRaw, type ComputedRef, type Ref } from 'vue';
import type { DataPath, ItemEntry, PrefixSuffixItem, RawData, SelectedGridItem } from '../types';
import { getByPath } from '../utils/deep-utils';
import { persistRawData } from '../utils/persist';
import { useDragList } from './useDragLists';

/**
 * 根据 path 列表重排原始容器，保留原始元素结构（包括单键对象的键名）
 * @param container 原始数组容器
 * @param paths 拖拽后的 path 顺序
 * @returns 重排后的数组
 */
function reorderByPaths(container: unknown[], paths: DataPath[]): unknown[] {
  return paths.map(path => {
    const lastKey = path[path.length - 1];
    // 单键对象场景：path = [arrayIndex, objectKey]，需要取 container[arrayIndex]
    if (path.length >= 2 && typeof path[path.length - 2] === 'number') {
      const idx = path[path.length - 2] as number;
      return toRaw(container[idx]);
    }
    // 普通数组元素场景：path = [arrayIndex]
    if (typeof lastKey === 'number') {
      return toRaw(container[lastKey]);
    }
    return null;
  }).filter(Boolean);
}

interface UseQuickSendDragListsOptions {
  rawData: RawData;
  editMode: Readonly<Ref<boolean>>;
  level1Entries: ComputedRef<ItemEntry[]>;
  level2Entries: ComputedRef<ItemEntry[]>;
  activeTabIndex: Readonly<Ref<number>>;
  gridPath: Readonly<Ref<number[]>>;
  gridBaseEntry: ComputedRef<ItemEntry | null>;
  gridCurrent: ComputedRef<{ labels: string[]; values: unknown[]; metas: Array<{ path: DataPath }> }>;
  computeGridEntries: (node: unknown, basePath: DataPath) => {
    labels: string[];
    values: unknown[];
    metas: Array<{ path: DataPath }>;
  };
  prefixList: ComputedRef<PrefixSuffixItem[]>;
  suffixList: ComputedRef<PrefixSuffixItem[]>;
  selectedGridItems: Ref<SelectedGridItem[]>;
  selectedPrefixIndexes: Ref<Set<number>>;
  selectedSuffixIndexes: Ref<Set<number>>;
  syncSelectedGridText: () => void;
}

/** 快捷指令面板拖拽列表编排：集中维护 6 个拖拽副本与 rawData 写回 */
export function useQuickSendDragLists(options: UseQuickSendDragListsOptions) {
  const isDragging = ref(false);
  const level1 = useDragList(options.level1Entries, isDragging, createLevel1Options(options));
  const level2 = useDragList(options.level2Entries, isDragging, createLevel2Options(options));
  const grid = useDragList(computed(() => options.gridCurrent.value.labels), isDragging, createGridOptions(options));
  const prefix = useDragList(options.prefixList, isDragging, createPrefixOptions(options));
  const suffix = useDragList(options.suffixList, isDragging, createSuffixOptions(options));
  const chips = useDragList(options.selectedGridItems, isDragging, createChipsOptions(options));

  /** 回传 L1 容器 ref */
  function setL1Ref(el: HTMLElement | null): void { level1.containerRef.value = el; }

  /** 回传 L2 容器 ref */
  function setL2Ref(el: HTMLElement | null): void { level2.containerRef.value = el; }

  /** 回传 Grid 容器 ref */
  function setGridRef(el: HTMLElement | null): void { grid.containerRef.value = el; }

  return {
    level1DragList: level1.dragList,
    level2DragList: level2.dragList,
    gridDragList: grid.dragList,
    prefixDragList: prefix.dragList,
    suffixDragList: suffix.dragList,
    chipsDragList: chips.dragList,
    setL1Ref,
    setL2Ref,
    setGridRef,
    setPrefixContainerRef: prefix.setContainerRef,
    setSuffixContainerRef: suffix.setContainerRef,
    setChipsRef: chips.setContainerRef,
  };
}

/** 创建 L1 拖拽写回配置 */
function createLevel1Options(options: UseQuickSendDragListsOptions) {
  return {
    enabled: options.editMode,
    draggable: '.level1-drag-item',
    handle: '.drag-handle-l1',
    filter: '.drag-exclude',
    onCommit: (_old: number, _next: number, list: ItemEntry[]) => {
      // 按拖拽后的顺序重排原始数据，保留单键对象结构
      options.rawData.data = reorderByPaths(options.rawData.data, list.map(e => e.path));
      persistRawData(options.rawData);
    },
  };
}

/** 创建 L2 拖拽写回配置 */
function createLevel2Options(options: UseQuickSendDragListsOptions) {
  return {
    enabled: options.editMode,
    draggable: '.level2-drag-item',
    handle: '.drag-handle-l2',
    filter: '.drag-exclude',
    onCommit: (_old: number, _next: number, list: ItemEntry[]) => commitLevel2Drag(options, list),
  };
}

/** 写回 L2 拖拽结果 */
function commitLevel2Drag(options: UseQuickSendDragListsOptions, list: ItemEntry[]): void {
  const l1Entry = options.level1Entries.value[options.activeTabIndex.value];
  if (!l1Entry || !Array.isArray(l1Entry.value)) return;

  // 按拖拽后的顺序重排 L2 数据，保留单键对象结构
  const reordered = reorderByPaths(l1Entry.value, list.map(e => e.path));

  // 写回到 rawData：path 长度区分 L1 元素形态
  const path = l1Entry.path;
  if (path.length === 1 && typeof path[0] === 'number') {
    // L1 对应 rawData.data 下的数组元素，可能是纯数组，也可能是单键对象包裹的数组
    const l1Element = options.rawData.data[path[0]];
    if (Array.isArray(l1Element)) options.rawData.data[path[0]] = reordered;
    else if (l1Element && typeof l1Element === 'object') {
      const key = Object.keys(l1Element)[0];
      if (key) options.rawData.data[path[0]] = { [key]: reordered };
    }
  } else if (path.length === 2 && typeof path[0] === 'number') {
    // L1 是单键/多键对象的某个键：用键名包裹重排数组
    options.rawData.data[path[0]] = { [path[1]]: reordered };
  }
  persistRawData(options.rawData);
}

/** 创建 Grid 拖拽写回配置 */
function createGridOptions(options: UseQuickSendDragListsOptions) {
  return {
    handle: '.drag-handle-grid',
    filter: '.drag-exclude',
    draggable: '.auto-grid-item:not(.drag-exclude)',
    onCommit: (oldIndex: number, newIndex: number) => commitGridDrag(options, oldIndex, newIndex),
  };
}

/** 写回 Grid 拖拽结果 */
function commitGridDrag(options: UseQuickSendDragListsOptions, oldIndex: number, newIndex: number): void {
  const currentPath = resolveGridPath(options);
  const target = getByPath(options.rawData.data, currentPath);
  const nextValue = reorderTarget(target, oldIndex, newIndex);
  if (nextValue == null) return;
  writeGridResult(options.rawData, currentPath, nextValue);
  persistRawData(options.rawData);
}

/** 解析当前 Grid 层级对应的数据路径 */
function resolveGridPath(options: UseQuickSendDragListsOptions): DataPath {
  const base = options.gridBaseEntry.value;
  if (!base) return [];
  let current: unknown = toRaw(base.value ?? null);
  let currentPath: DataPath = [...base.path];
  for (const idx of options.gridPath.value) {
    const step = options.computeGridEntries(current, currentPath);
    if (step.metas[idx]) currentPath = step.metas[idx].path;
    current = toRaw(step.values[idx]);
  }
  return currentPath;
}

/** 重排数组或对象目标 */
function reorderTarget(target: unknown, oldIndex: number, newIndex: number): unknown {
  if (Array.isArray(target)) return reorderArray(target, oldIndex, newIndex);
  if (target && typeof target === 'object') return reorderObject(target, oldIndex, newIndex);
  return null;
}

/** 重排数组目标 */
function reorderArray(target: unknown[], oldIndex: number, newIndex: number): unknown[] {
  const arr = target.map(item => toRaw(item));
  const [moved] = arr.splice(oldIndex, 1);
  arr.splice(newIndex, 0, moved);
  return arr;
}

/** 重排对象目标 */
function reorderObject(target: object, oldIndex: number, newIndex: number): Record<string, unknown> {
  const rawObj = toRaw(target as Record<string, unknown>);
  const keys = Object.keys(rawObj);
  const [movedKey] = keys.splice(oldIndex, 1);
  keys.splice(newIndex, 0, movedKey);
  return Object.fromEntries(keys.map(key => [key, toRaw(rawObj[key])]));
}

/** 将重排后的 Grid 结果写回 rawData */
function writeGridResult(rawData: RawData, path: DataPath, value: unknown): void {
  if (path.length === 0) {
    rawData.data = value as unknown[];
    return;
  }
  const parentPath = path.slice(0, -1);
  const targetKey = path[path.length - 1];
  const parent = parentPath.length === 0 ? rawData.data : getByPath(rawData.data, parentPath);
  if (Array.isArray(parent) && typeof targetKey === 'number') parent[targetKey] = value;
  if (parent && typeof parent === 'object' && typeof targetKey === 'string') {
    (parent as Record<string, unknown>)[targetKey] = value;
  }
}

/** 创建前缀拖拽写回配置 */
function createPrefixOptions(options: UseQuickSendDragListsOptions) {
  return {
    handle: '.drag-handle-prefix',
    filter: '.drag-exclude',
    draggable: '.auto-grid-item:not(.drag-exclude)',
    onCommit: (oldIndex: number, newIndex: number, list: PrefixSuffixItem[]) => {
      // 记录拖拽前选中的数据项
      const selectedItems = Array.from(options.selectedPrefixIndexes.value)
        .map(idx => options.prefixList.value[idx])
        .filter(Boolean);

      // 写回数据
      if (options.rawData.perfix) options.rawData.perfix = list;
      else options.rawData.prefix = list;
      persistRawData(options.rawData);

      // 重新映射选中索引：找到之前选中的数据项在新列表中的位置
      const newSelectedIndexes = new Set<number>();
      selectedItems.forEach(item => {
        const newIdx = list.findIndex(listItem => listItem === item);
        if (newIdx >= 0) newSelectedIndexes.add(newIdx);
      });
      options.selectedPrefixIndexes.value = newSelectedIndexes;
    },
  };
}

/** 创建后缀拖拽写回配置 */
function createSuffixOptions(options: UseQuickSendDragListsOptions) {
  return {
    handle: '.drag-handle-suffix',
    filter: '.drag-exclude',
    draggable: '.auto-grid-item:not(.drag-exclude)',
    onCommit: (oldIndex: number, newIndex: number, list: PrefixSuffixItem[]) => {
      // 记录拖拽前选中的数据项
      const selectedItems = Array.from(options.selectedSuffixIndexes.value)
        .map(idx => options.suffixList.value[idx])
        .filter(Boolean);

      // 写回数据
      options.rawData.suffix = list;
      persistRawData(options.rawData);

      // 重新映射选中索引：找到之前选中的数据项在新列表中的位置
      const newSelectedIndexes = new Set<number>();
      selectedItems.forEach(item => {
        const newIdx = list.findIndex(listItem => listItem === item);
        if (newIdx >= 0) newSelectedIndexes.add(newIdx);
      });
      options.selectedSuffixIndexes.value = newSelectedIndexes;
    },
  };
}

/** 创建已选 chips 拖拽写回配置 */
function createChipsOptions(options: UseQuickSendDragListsOptions) {
  return {
    draggable: '.p-chip',
    filter: '.p-chip-remove-icon, [data-pc-section="removeicon"]',
    preventOnFilter: false,
    onCommit: (_old: number, _next: number, list: SelectedGridItem[]) => {
      options.selectedGridItems.value = [...list];
      options.syncSelectedGridText();
    },
  };
}
