import _ from 'lodash';
import { toRaw } from 'vue';
import type { RawData } from '../types';

/**
 * 持久化 rawData 到脚本变量
 * 统一处理 cloneDeep + toRaw（去 reactive proxy） + script_id 注入
 * 用于替换组件内重复的 replaceVariables(...) 调用（迁移留给 P1）
 */
export function persistRawData(data: RawData): void {
  // @ts-expect-error replaceVariables / getScriptId 来自酒馆助手全局接口
  replaceVariables(_.cloneDeep(toRaw(data)), { type: 'script', script_id: getScriptId() });
}
