import { watch } from 'vue';
import type { RawData } from '../types';
import { persistRawData } from '../utils/persist';
import { useSelectionModel } from './useSelectionModel';

/** 快捷指令面板选中状态编排：Grid chips、Grid 高亮、前后缀多选 */
export function useQuickSendSelection(rawData: RawData) {
  const gridSelection = useSelectionModel({ mode: 'ordered-list' });
  const gridHighlight = useSelectionModel(createGridHighlightPersist());
  const prefixSelection = useSelectionModel(createPrefixPersist());
  const suffixSelection = useSelectionModel(createSuffixPersist());

  restoreSelectedPrefixSuffix(rawData, prefixSelection.selected, suffixSelection.selected);
  persistSelectedPrefixSuffix(rawData, prefixSelection.selected, suffixSelection.selected);

  return {
    gridSelection,
    selectedGridItems: gridSelection.selected,
    selectedGridIndex: gridHighlight.selected,
    prefixSelection,
    suffixSelection,
    selectedPrefixIndexes: prefixSelection.selected,
    selectedSuffixIndexes: suffixSelection.selected,
  };
}

/** 创建 Grid 高亮持久化配置 */
function createGridHighlightPersist() {
  return {
    mode: 'single' as const,
    persist: {
      key: 'quicksend:lastSelection',
      serialize: (val: number | null) => ({ ...readStoredObject('quicksend:lastSelection'), sel: val }),
      deserialize: (val: { sel?: number | null } | null) => val?.sel ?? null,
    },
  };
}

/** 创建前缀多选持久化配置 */
function createPrefixPersist() {
  return {
    mode: 'multi-set' as const,
    persist: {
      key: 'quicksend:selectedPrefixSuffix',
      serialize: (val: Set<number>) => mergePrefixSuffix({ prefix: Array.from(val) }),
      deserialize: (val: unknown) => readPrefixSuffixSet(val, 'prefix'),
    },
  };
}

/** 创建后缀多选持久化配置 */
function createSuffixPersist() {
  return {
    mode: 'multi-set' as const,
    persist: {
      key: 'quicksend:selectedPrefixSuffix',
      serialize: (val: Set<number>) => mergePrefixSuffix({ suffix: Array.from(val) }),
      deserialize: (val: unknown) => readPrefixSuffixSet(val, 'suffix'),
    },
  };
}

/** 读取 localStorage 对象 */
function readStoredObject(key: string): Record<string, unknown> {
  try {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : {};
  } catch {
    return {};
  }
}

/** 合并前后缀选择持久化值 */
function mergePrefixSuffix(patch: { prefix?: number[]; suffix?: number[] }) {
  const base = readStoredPrefixSuffix();
  return [{ ...base, ...patch }];
}

/** 读取前后缀选择持久化值 */
function readStoredPrefixSuffix(): { prefix: number[]; suffix: number[] } {
  const stored = readStoredObject('quicksend:selectedPrefixSuffix');
  if (Array.isArray(stored) && stored[0]) return normalizePrefixSuffix(stored[0]);
  return { prefix: [], suffix: [] };
}

/** 规范化前后缀选择对象 */
function normalizePrefixSuffix(value: unknown): { prefix: number[]; suffix: number[] } {
  const item = value as { prefix?: unknown; suffix?: unknown };
  return {
    prefix: Array.isArray(item.prefix) ? item.prefix : [],
    suffix: Array.isArray(item.suffix) ? item.suffix : [],
  };
}

/** 从持久化值读取 Set */
function readPrefixSuffixSet(value: unknown, key: 'prefix' | 'suffix'): Set<number> {
  if (!Array.isArray(value) || !value[0]) return new Set();
  const list = normalizePrefixSuffix(value[0])[key];
  return new Set(list);
}

/** 从 rawData 恢复前后缀选中状态 */
function restoreSelectedPrefixSuffix(
  rawData: RawData,
  selectedPrefixIndexes: { value: Set<number> },
  selectedSuffixIndexes: { value: Set<number> },
): void {
  const saved = rawData.selectedPrefixSuffix?.[0];
  if (!saved) return;
  if (Array.isArray(saved.prefix)) selectedPrefixIndexes.value = new Set(saved.prefix);
  if (Array.isArray(saved.suffix)) selectedSuffixIndexes.value = new Set(saved.suffix);
}

/** 持久化前后缀选中状态到 rawData */
function persistSelectedPrefixSuffix(
  rawData: RawData,
  selectedPrefixIndexes: { value: Set<number> },
  selectedSuffixIndexes: { value: Set<number> },
): void {
  watch(
    [selectedPrefixIndexes, selectedSuffixIndexes],
    () => {
      rawData.selectedPrefixSuffix = [{
        prefix: Array.from(selectedPrefixIndexes.value),
        suffix: Array.from(selectedSuffixIndexes.value),
      }];
      persistRawData(rawData);
    },
    { deep: true },
  );
}
